import re,sys,os,glob,subprocess
sys.path.insert(0,'tools')
import nid_names as N
from pathlib import Path
db=N.load_db(N.DEFAULT_CACHE)
def exports(lib):
    res={}  # nid -> (func, stub?)
    files=[f for f in glob.glob(f'core/libs/prx/{lib}/**/*.cpp',recursive=True)]
    for f in files:
        s=open(f,errors='replace').read()
        stubs=set(re.findall(r'APS5_VABI\s+(\w+)\s*\([^)]*\)\s*\{\s*NotImplemented_nid_no_patch\(__func__\);\s*\}',s))
        for nid,fn in re.findall(r'APS5_EXPORT\(\s*"([^"]+)"\s*,\s*(\w+)\s*\)',s):
            res[nid]=(fn, fn in stubs, f)
        for fn in re.findall(r'APS5_VABI\s+(\w+_nid_postfix)\s*\(',s):
            name=N.strip_nid_postfix(fn)
            nid=N.compute_nid(name)
            if nid not in res: res[nid]=(fn, fn in stubs, f)
        for fn in stubs:
            if fn.endswith('_nid_postfix'):
                nid=N.compute_nid(N.strip_nid_postfix(fn)); res[nid]=(fn,True,f)
    return res
li=exports('libSceLibcInternal'); lc=exports('libc')
print('internal',len(li),'stubs',sum(1 for v in li.values() if v[1]),'libc',len(lc))
for nid,(fn,stub,f) in sorted(li.items(), key=lambda x: db.get(x[0],'')):
    if stub and nid in lc and not lc[nid][1]:
        print('MATCH',nid,db.get(nid,'?'),fn,f,'<-',lc[nid][0],lc[nid][2])
print('---named stubs in internal not in libc (first 150)')
c=0
for nid,(fn,stub,f) in sorted(li.items(), key=lambda x: db.get(x[0],'')):
    if stub and nid not in lc and nid in db:
        print(nid,db[nid],fn); c+=1
        if c>150: break
EOF
